UPDATE public.global_client_logos g
SET files = COALESCE((SELECT jsonb_agg(elem) FROM jsonb_array_elements(g.files) elem WHERE elem->>'lockup' <> 'wordmark'), '[]'::jsonb)
  || jsonb_build_array(
    jsonb_build_object('variant','color','format','png','lockup','wordmark','source','wikimedia','url', o.logo_url),
    jsonb_build_object('variant','black','format','png','lockup','wordmark','source','wikimedia','url', o.logo_url),
    jsonb_build_object('variant','white','format','png','lockup','wordmark','source','wikimedia','url', o.logo_url)
  ),
  updated_at = now()
FROM overrides o
WHERE g.name = o.brand_name;